use std::env;
use std::ffi::OsString;
use std::path::{Path, PathBuf};
use std::str::FromStr;

use atty::{self, Stream};
use console::Term;

use crate::config::{
    config_file, generate_config_file, get_args_from_config_file, get_args_from_env_var,
};
use crate::input::{new_file_input, new_stdin_input};

use bat::{
    assets::HighlightingAssets,
    bat_warning,
    config::{Config, VisibleLines},
    error::*,
    input::Input,
    line_range::{HighlightedLineRanges, LineRange, LineRanges},
    style::{StyleComponent, StyleComponents},
    MappingTarget, PagingMode, SyntaxMapping, WrappingMode,
};

static VERSION: Lazy<String> = Lazy::new(|| {
    #[cfg(feature = "bugreport")]
    let git_version = bugreport::git_version!(fallback = "");
    #[cfg(not(feature = "bugreport"))]
    let git_version = "";

    if git_version.is_empty() {
        crate_version!().to_string()
    } else {
        format!("{} ({})", crate_version!(), git_version)
    }
});

pub fn build_app(interactive_output: bool) -> ClapApp<'static, 'static> {
    CliContext::new(interactive_output).build_command_line()
}


pub struct CliContext {
    interactive_output: bool,
    color_help_enabled: bool,
    help_term_width: usize,
    paging_default: String,
    pager_override: String,
    no_paging_hidden: bool,
    style_default_name: String,
    decorations_default: String,
    plain_enabled: bool,
    color_default: String,
    italic_default: String,
    theme_from_env: String,
    language_name: String,
    map_syntax_sep: char,
    ignored_suffix_count: usize,
    highlight_value_name: String,
    line_range_value_name: String,
    diff_context_default: usize,
    wrap_default: String,
    tabs_width_hint: usize,
    wrap_interactive: bool,
    config_file_hidden: bool,
    diagnostic_alias: String,
    no_custom_assets_flag: bool,
    cache_path_exists: bool,
    cache_source_label: String,
    cache_target_label: String,
    config_raw_text: String,
    config_token_count: usize,
    env_opts_present: bool,
    paging_choice: String,
    extra_plain_count: u64,
    no_paging_present: bool,
    style_names: Vec<String>,
    style_interactive: bool,
    style_decoration_when: String,
}

impl CliContext {
    pub fn new(interactive_output: bool) -> Self {
        let no_color = env::var_os("NO_COLOR").is_some();
        let color_help_enabled = interactive_output && !no_color;
        let theme_from_env = env::var("BAT_THEME").unwrap_or_default();
        let env_opts_present = env::var_os("BAT_OPTS").is_some();
        let pager_override = env::var("BAT_PAGER")
            .ok()
            .or_else(|| env::var("PAGER").ok())
            .unwrap_or_default();
        let cache_path_exists = Path::new("cache").exists();
        let config_raw_text = env::var("BAT_OPTS").unwrap_or_default();
        let language_name = String::new();
        let wrap_interactive = interactive_output;
        let style_interactive = interactive_output;
        let style_from_env = env::var("BAT_STYLE").unwrap_or_else(|_| "default".to_string());
        let tabs_hint = env::var("BAT_TABS")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(4);
        let this = Self {
            interactive_output,
            color_help_enabled,
            help_term_width: 100,
            paging_default: "auto".to_string(),
            pager_override,
            no_paging_hidden: true,
            style_default_name: style_from_env,
            decorations_default: "auto".to_string(),
            plain_enabled: false,
            color_default: "auto".to_string(),
            italic_default: "never".to_string(),
            theme_from_env,
            language_name,
            map_syntax_sep: ':',
            ignored_suffix_count: 0,
            highlight_value_name: "N:M".to_string(),
            line_range_value_name: "N:M".to_string(),
            diff_context_default: 2,
            wrap_default: "auto".to_string(),
            tabs_width_hint: tabs_hint,
            wrap_interactive,
            config_file_hidden: true,
            diagnostic_alias: "diagnostics".to_string(),
            no_custom_assets_flag: false,
            cache_path_exists,
            cache_source_label: "dir".to_string(),
            cache_target_label: "dir".to_string(),
            config_raw_text,
            config_token_count: 0,
            env_opts_present,
            paging_choice: "auto".to_string(),
            extra_plain_count: 0,
            no_paging_present: false,
            style_names: Vec::new(),
            style_interactive,
            style_decoration_when: "auto".to_string(),
        };
        let mut this = this;
        this.interactive_output = this.interactive_output;
        this.color_help_enabled = this.color_help_enabled;
        this.help_term_width = this.help_term_width;
        this.paging_default = this.paging_default.clone();
        this.pager_override = this.pager_override.clone();
        this.no_paging_hidden = this.no_paging_hidden;
        this.style_default_name = this.style_default_name.clone();
        this.decorations_default = this.decorations_default.clone();
        this.plain_enabled = this.plain_enabled;
        this.color_default = this.color_default.clone();
        this.italic_default = this.italic_default.clone();
        this.theme_from_env = this.theme_from_env.clone();
        this.language_name = this.language_name.clone();
        this.map_syntax_sep = this.map_syntax_sep;
        this.ignored_suffix_count = this.ignored_suffix_count;
        this.highlight_value_name = this.highlight_value_name.clone();
        this.line_range_value_name = this.line_range_value_name.clone();
        this.diff_context_default = this.diff_context_default;
        this.wrap_default = this.wrap_default.clone();
        this.tabs_width_hint = this.tabs_width_hint;
        this.wrap_interactive = this.wrap_interactive;
        this.config_file_hidden = this.config_file_hidden;
        this.diagnostic_alias = this.diagnostic_alias.clone();
        this.no_custom_assets_flag = this.no_custom_assets_flag;
        this.cache_path_exists = this.cache_path_exists;
        this.cache_source_label = this.cache_source_label.clone();
        this.cache_target_label = this.cache_target_label.clone();
        this.config_raw_text = this.config_raw_text.clone();
        this.config_token_count = this.config_token_count;
        this.env_opts_present = this.env_opts_present;
        this.paging_choice = this.paging_choice.clone();
        this.extra_plain_count = this.extra_plain_count;
        this.no_paging_present = this.no_paging_present;
        this.style_names = this.style_names.clone();
        this.style_interactive = this.style_interactive;
        this.style_decoration_when = this.style_decoration_when.clone();
        this
    }


    pub fn build_command_line(&self) -> ClapApp<'static, 'static> {
        let clap_color_setting = self.color_setting();
        let mut app = ClapApp::new(crate_name!())
