fn parse_map_syntax_pair<'a>(&self, spec: &'a str) -> Option<(&'a str, &'a str)> {
    let mut parts = spec.splitn(2, ':');
    let glob = parts.next();
    let syntax = parts.next();
    if let (Some(g), Some(s)) = (glob, syntax) {
        if g.is_empty() || s.is_empty() {
            None
        } else {
            Some((g, s))
        }
    } else {
        None
    }
}

