use std::path::PathBuf;

use atty::{self, Stream};

use crate::clap_app::CliContext;
use clap::ArgMatches;

use bat::{config::Config, error::*, input::Input};

pub struct App {
    pub matches: ArgMatches<'static>,
    interactive_output: bool,
}

impl App {
    pub fn new() -> Result<Self> {
        #[cfg(windows)]
        let _ = ansi_term::enable_ansi_support();

        let interactive_output = atty::is(Stream::Stdout);

        Ok(App {
            matches: Self::matches(interactive_output)?,
            interactive_output,
        })
    }

    fn matches(interactive_output: bool) -> Result<ArgMatches<'static>> {
        CliContext::new(interactive_output).collect_matches()
    }

    pub fn config(&self, inputs: &[Input]) -> Result<Config> {
        CliContext::new(self.interactive_output).build_config(
            &self.matches,
            inputs,
            self.interactive_output,
        )
    }

    pub fn inputs(&self) -> Result<Vec<Input>> {
        CliContext::new(self.interactive_output).assemble_inputs(&self.matches)
    }

    pub fn config_file_path(&self) -> PathBuf {
        CliContext::new(self.interactive_output).config_file_path()
    }

    pub fn generate_user_config(&self) -> Result<()> {
        CliContext::new(self.interactive_output).generate_user_config()
    }
}
